import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.DDY-poMm.js";const m=JSON.parse('{"title":"Predict (BTX Predict and Polymarket)","description":"","frontmatter":{},"headers":[],"relativePath":"wallet/predict.md","filePath":"wallet/predict.md","lastUpdated":1793861367000}'),n={name:"wallet/predict.md"};function s(i,e,d,l,c,p){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="predict-btx-predict-and-polymarket" tabindex="-1">Predict (BTX Predict and Polymarket) <a class="header-anchor" href="#predict-btx-predict-and-polymarket" aria-label="Permalink to &quot;Predict (BTX Predict and Polymarket)&quot;">​</a></h1><p>The Predict tab has two sections, &quot;BTX Predict&quot; and &quot;Polymarket&quot;, with separate accounts and funds.</p><p><strong>BTX Predict (the platform&#39;s own market)</strong>: Yes / No markets and BTC Up / Down rounds. Yes / No markets are made automatically by the platform; Up / Down uses an order book with continuous platform quotes. Authorized contributors can create markets that go live after review and share trading fees; results have a public dispute window. Users sign in with the wallet; after depositing USDT, they trade and settle in their prediction account on the platform.</p><p><strong>Polymarket (a leading global prediction market)</strong>: browse trending Polymarket events by category or search, with probability charts, order books and rules. Open an account controlled by the user&#39;s own private key in one tap; the platform never touches the funds. Deposit Solana USDC or BNB Chain USDT and withdraw back to the user&#39;s own Solana address. Market and limit orders, 2% slippage protection on market orders, and fees listed before every order. Positions, open orders, cancellation and payouts are all handled in the wallet. Users in restricted regions can only sell existing positions.</p><h2 id="risk-notes" tabindex="-1">Risk notes <a class="header-anchor" href="#risk-notes" aria-label="Permalink to &quot;Risk notes&quot;">​</a></h2><ul><li>Predictions can lose money; cross-chain deposits and withdrawals are handled by Polymarket&#39;s official bridge, and confirmed on-chain transfers cannot be reversed.</li></ul>',6)])])}const u=t(n,[["render",s]]);export{m as __pageData,u as default};
